        print(f"{p}: indisponibil")

CP5.2.5.solutie:
def citeste_sigur(nume):
    try:
        with open(nume, encoding="utf-8") as f:
            return f.read()
    except FileNotFoundError:
        return "Fișierul nu există."

print(citeste_sigur("lipsa.txt"))

